#include <iostream>
#include <string>

int main() {
    std::string s2 = "abc 123.45 def";  // Example string with mixed content
    size_t pos = s2.find_first_of("+-.0123456789");  // Find first potential number character
    if (pos != std::string::npos) {  // Check if a position was found
        std::string numStr = s2.substr(pos);  // Extract substring from that position
        try {
            double d = std::stod(numStr);  // Convert substring to double
            std::cout << "Converted value: " << d << std::endl;  // Output the result
        } catch (const std::invalid_argument& e) {
            std::cout << "Error: Invalid argument - " << e.what() << std::endl;  // Handle invalid input
        } catch (const std::out_of_range& e) {
            std::cout << "Error: Number out of range - " << e.what() << std::endl;  // Handle overflow
        }
    } else {
        std::cout << "No potential number found in the string." << std::endl;  // Handle no match
    }
    return 0;
}
